 final HalfSwordView view;final File result;final int surfaceGeneration;final Handler handler=new Handler(Looper.getMainLooper());
 final long started=SystemClock.uptimeMillis();String restPixels,runPixels;boolean baselinePassed,momentumPassed;int heldSteps;long gripReactionStart,heldTargetStart,heldContactSamples;double heldOffset,heldVx,heldVy,heldVz,heldX,heldY,heldZ;double releasedX,releasedY,releasedZ;int releasedSteps;double releasedDistance;long motorStart,captureStart,runCaptures;long forcedStart;int stage,pausedSteps;long mark;long presented;
 HalfSwordRunCheck(HalfSwordView v){view=v;surfaceGeneration=v.generation;result=new File(v.getContext().getFilesDir(),"home/.trough/half-sword-run-check-result.json");}
