 static void maybeRun(final HalfSwordView v){final File ticket=request(v);if(!ticket.isFile()||v.runCheckWaiting)return;v.runCheckWaiting=true;final Handler ui=new Handler(Looper.getMainLooper());final long began=SystemClock.uptimeMillis();ui.post(new Runnable(){public void run(){if(!ticket.isFile()){v.runCheckWaiting=false;return;}int decision=HalfSwordCheckGate.decide(v.getParent()!=null,v.isAttachedToWindow(),v.renderVisible,v.isAvailable(),v.drawCount,v.generation,-1,SystemClock.uptimeMillis()-began);if(decision==HalfSwordCheckGate.RETIRED||decision==HalfSwordCheckGate.DEFER){v.runCheckWaiting=false;return;}if(decision==HalfSwordCheckGate.WAIT){ui.postDelayed(this,100);return;}v.runCheckWaiting=false;if(ticket.delete()){HalfSwordRunCheck check=new HalfSwordRunCheck(v);if(decision==HalfSwordCheckGate.READY)check.handlerPost();else check.finish("View never became ready");}}});}
 void handlerPost(){handler.postDelayed(this,100);}
 Button find(View node,String text){if(node instanceof Button&&(text.contentEquals(((Button)node).getText())||(((Button)node).getContentDescription()!=null&&text.contentEquals(((Button)node).getContentDescription()))))return (Button)node;if(node instanceof ViewGroup){ViewGroup group=(ViewGroup)node;for(int i=0;i<group.getChildCount();i++){Button b=find(group.getChildAt(i),text);if(b!=null)return b;}}return null;}
 void click(String text)throws Exception{Button b=find(view.controlsRoot(),text);if(b==null||!b.performClick())throw new Exception("Missing control "+text);}
 String capture(String name)throws Exception{android.graphics.Bitmap bitmap=view.getBitmap();if(bitmap==null)throw new Exception("No presented bitmap");try{java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();if(!bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes))throw new Exception("PNG capture failed");byte[] png=bytes.toByteArray();File file=new File(view.getContext().getFilesDir(),"home/.trough/half-sword-run-"+name+".png");try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){out.write(png);}byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest(png);StringBuilder hash=new StringBuilder();for(byte v:digest)hash.append(String.format(java.util.Locale.US,"%02x",v&255));return hash.toString();}finally{bitmap.recycle();}}
 void touchPush(int action)throws Exception{Button b=find(view.controlsRoot(),"Push +X");if(b==null)throw new Exception("Push control unavailable");long now=SystemClock.uptimeMillis();android.view.MotionEvent event=android.view.MotionEvent.obtain(now,now,action,b.getWidth()/2f,b.getHeight()/2f,0);try{need(b.dispatchTouchEvent(event),"Push touch rejected");}finally{event.recycle();}}
 void touchArm()throws Exception{android.widget.SeekBar bar=view.rightArmControl;need(bar!=null&&bar.getWidth()>0,"Arm slider unavailable");float x=bar.getPaddingLeft()+(bar.getWidth()-bar.getPaddingLeft()-bar.getPaddingRight())*65f/90f;long now=SystemClock.uptimeMillis();for(int action:new int[]{android.view.MotionEvent.ACTION_DOWN,android.view.MotionEvent.ACTION_UP}){android.view.MotionEvent event=android.view.MotionEvent.obtain(now,now,action,x,bar.getHeight()/2f,0);try{need(bar.dispatchTouchEvent(event),"Arm touch rejected");}finally{event.recycle();}}need(view.characterMotorEnabled&&view.characterRightPitch!=0,"Arm slider did not request motor");}
