 void finish(String error){try{JSONObject out=new JSONObject();out.put("blade_floor_probe_frames",view.bladeFloorProbeFrames).put("blade_floor_contact_frames",view.bladeFloorContactFrames).put("blade_floor_reaction_frames",view.bladeFloorReactionFrames).put("check_version",13).put("passed",error==null).put("error",error==null?"":error).put("stage",stage).put("held_force_frames",view.characterForcedFrames-forcedStart).put("target_reaction_frames",view.targetReactionFrames).put("target_clear_frames",view.targetClearFrames).put("target_transitions",view.targetTransitions).put("target_probe_frames",view.targetProbeFrames).put("target_contact_frames",view.targetContactFrames).put("weapon_attached",view.weaponAttached).put("view_width",view.getWidth()).put("view_height",view.getHeight()).put("automatic_captures_during_run",runCaptures).put("baseline_passed",baselinePassed).put("compliant_hold_tested",stage==23).put("held_body_steps",heldSteps).put("held_body_offset",heldOffset).put("held_contact_samples",heldContactSamples).put("release_momentum_tested",momentumPassed).put("released_body_tested",baselinePassed).put("released_body_steps",releasedSteps).put("released_body_distance",releasedDistance).put("aim_pad_tested",stage>=10).put("motor_frames",view.characterMotorFrames-motorStart).put("run_steps",pausedSteps).put("rest_png_sha256",restPixels).put("paused_png_sha256",runPixels).put("native_module_sha256",HalfSwordBridge.loadedModuleSha256).put("presented_frames",view.presentedCount).put("elapsed_ms",SystemClock.uptimeMillis()-started).put("time_ms",System.currentTimeMillis());Payloads.writeSmall(result,out.toString());}catch(Exception ignored){}}
